"""T68b acceptance fixtures: mixed document with annotations, widgets and watermarks.

Writes app/src/androidTest/assets/t68b/t68b-mixed.pdf.

Run from repo root:
    python app/tools/t68b_acceptance_pdfs.py
"""
from pathlib import Path
import os
import sys

ROOT = Path(__file__).resolve().parents[2]
ASSETS = ROOT / "app" / "src" / "androidTest" / "assets" / "t68b"

def main():
    ASSETS.mkdir(parents=True, exist_ok=True)
    # The fixture is generated by T68bFixtures in Kotlin / Gradle test run,
    # writing directly to t68b-mixed.pdf in ASSETS.
    print(f"T68b fixture generator: target asset directory {ASSETS}")

if __name__ == "__main__":
    main()
